-- Empty targets preserve each existing pet skill's single SourceAttr target.
ALTER TABLE game_pet_skill_effects
    ADD COLUMN IF NOT EXISTS cleanse_status_ids INT[] NOT NULL DEFAULT '{}';

-- Trial configuration and durable per-character counters.
ALTER TABLE characters ADD COLUMN trial_day integer NOT NULL DEFAULT 0,
 ADD COLUMN trial_daily_completed integer NOT NULL DEFAULT 0 CHECK (trial_daily_completed >= 0),
 ADD COLUMN trial_cycle integer NOT NULL DEFAULT 0 CHECK (trial_cycle BETWEEN 0 AND 5),
 ADD COLUMN trial_monster_level integer NOT NULL DEFAULT 0 CHECK (trial_monster_level >= 0);
CREATE TABLE game_trial_rules (
 id integer PRIMARY KEY CHECK(id=1), normal_count integer NOT NULL CHECK(normal_count>0), boss_count integer NOT NULL CHECK(boss_count>0), quest_id integer NOT NULL, min_level integer NOT NULL,
 max_level integer NOT NULL, anchor_level integer NOT NULL, anchor_units integer NOT NULL,
 boss_offset integer NOT NULL, penalty_gap integer NOT NULL, penalty_per_level integer NOT NULL,
 first_pct integer NOT NULL, reward_chance integer NOT NULL, reward_min integer NOT NULL,
 reward_max integer NOT NULL, pill_id integer NOT NULL REFERENCES game_items(id), fragment_id integer NOT NULL REFERENCES game_items(id));
CREATE TABLE game_trial_rounds (cycle integer PRIMARY KEY, experience_pct integer NOT NULL CHECK(experience_pct>0));
CREATE TABLE game_trial_entrances (claim_map integer PRIMARY KEY REFERENCES map_defs(id), entry_map integer NOT NULL REFERENCES map_defs(id), claim_npc text NOT NULL, entry_npc text NOT NULL);
CREATE TABLE game_trial_spawns (map_id integer NOT NULL REFERENCES game_dungeons(map_id), spawn_id integer NOT NULL,
 x integer NOT NULL, y integer NOT NULL, dir integer NOT NULL, candidates integer[] NOT NULL CHECK(cardinality(candidates)>0), PRIMARY KEY(map_id,spawn_id));
CREATE TABLE game_trial_monster_stats (monster_id integer NOT NULL REFERENCES game_monsters(id), level integer NOT NULL,
 hp integer NOT NULL CHECK(hp>0), atk_min integer NOT NULL, atk_max integer NOT NULL, matk integer NOT NULL,
 def integer NOT NULL, mdef integer NOT NULL, hit integer NOT NULL, boss boolean NOT NULL, ai_template text NOT NULL REFERENCES game_monster_ai_templates(id), PRIMARY KEY(monster_id,level));
-- Use existing template HP/type, user-approved linear HP and existing server attack formulas.
 SELECT m.id,l, greatest(1,m.hp*l/10), round(l*2*type_atk*identity*0.8), round(l*2*type_atk*identity*1.2),
 round(l*2*type_matk*identity), l, floor(l*0.4), l*3, is_boss, CASE WHEN m.combat_type='法系' THEN 'caster' ELSE 'melee' END
 FROM game_monsters m
 CROSS JOIN generate_series(12,63) l
 CROSS JOIN LATERAL (SELECT m.id IN (3147,3148,3154,3155,3161,3162,3168,3169,3175,3176) AS is_boss,
 CASE WHEN m.id IN (3147,3148,3154,3155,3161,3162,3168,3169,3175,3176) THEN 2.0 ELSE 1.0 END AS identity,
 CASE m.combat_type WHEN '重型' THEN 0.75 WHEN '器物' THEN 0.75 WHEN '法系' THEN 0.5 WHEN '刺客' THEN 1.4 ELSE 1.0 END AS type_atk,
 CASE m.combat_type WHEN '重型' THEN 0.75 WHEN '器物' THEN 0.75 WHEN '法系' THEN 1.6 WHEN '刺客' THEN 0.5 ELSE 1.0 END AS type_matk) rates
 WHERE m.id BETWEEN 3142 AND 3176;
 VALUES(3289,200,0,1800) ON CONFLICT(item_id) DO UPDATE SET player_bonus_pct=200,pet_bonus_pct=0,duration_sec=1800;
ALTER TABLE game_trial_entrances ADD COLUMN price BIGINT NOT NULL DEFAULT 5000 CHECK (price >= 0);

-- Original animated gate object 19924845 in each GSM. Only the server trigger
-- is added; the official client already renders the gate.
 SELECT m.file,90001,d.exit_map_id,d.exit_x,d.exit_y,67,g.x,g.y,67,'',
 ARRAY[g.x-64,g.y-32,g.x,g.y-64,g.x+64,g.y-32,g.x,g.y]
 FROM (VALUES (21100,9790,5117),(21200,3068,4418),(21300,6858,6418),
 (21400,12063,3084),(21500,7003,2586)) AS g(map_id,x,y)
 JOIN map_defs m ON m.id=g.map_id JOIN game_dungeons d ON d.map_id=g.map_id;

CREATE TABLE game_pet_carrier_items (
 pet_id INT PRIMARY KEY,
 item_id INT NOT NULL UNIQUE REFERENCES game_items(id),
 bag_tab SMALLINT NOT NULL DEFAULT 3 CHECK(bag_tab BETWEEN 0 AND 3),
 icon INT NOT NULL DEFAULT 3633 CHECK(icon>0)
);
-- Server-owned pet item templates. The existing QQ pet-egg icon is reused;
-- actual species, name and instance details are sent in the native PetBrief.
 SELECT 1800000000+pet_id,name,decode('','hex'),0,0 FROM (SELECT DISTINCT ON(pet_id) pet_id,name FROM gamedata.ov_petgrow WHERE pet_id>0 ORDER BY pet_id,row_no) p;
 SELECT pet_id,1800000000+pet_id FROM (SELECT DISTINCT ON(pet_id) pet_id,name FROM gamedata.ov_petgrow WHERE pet_id>0 ORDER BY pet_id,row_no) p;
CREATE TABLE char_pet_items (
 char_id BIGINT NOT NULL,
 inst_id BIGINT NOT NULL,
 item_uid BIGINT NOT NULL CHECK(item_uid>0),
 PRIMARY KEY(char_id,inst_id),
 UNIQUE(item_uid) DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(char_id,inst_id) REFERENCES char_pets(char_id,inst_id) ON DELETE CASCADE,
 FOREIGN KEY(item_uid) REFERENCES item_instances(uid)
);
